var n=`0229-arroz-doce`;var s=`world-0229`;var t=`PT`;var a=`southern-europe`;var r=4;var o=26;var l={en:`Arroz Doce`,ua:`Солодкий рис по-португальськи`};var d={en:`A traditional Portugal dish made with whole cow milk, calrose rice, lemon zest. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Португалія. Основні інгредієнти: цільне коров'яче молоко, рис калроуз, цедра лимона. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`whole-cow-milk`,900,`ml`],[`water`,250,`ml`],[`calrose-rice`,180,`g`],[`ceylon-cinnamon`,1,`pcs`],[`lemon-zest`,6,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:6,i:[[`white-granulated-sugar`,130,`g`],[`unsalted-butter`,20,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ground-cinnamon`,3,`g`]]}];var h={slug:n,id:s,country:`PT`,region:a,servings:4,minutes:26,title:l,text:d,steps:g};export{t as country,h as default,s as id,o as minutes,a as region,r as servings,n as slug,g as steps,d as text,l as title};